/// Attempt to do a fast confirmation of a word match that covers a subset
/// (but hopefully a big subset) of most cases. Ok(Some(..)) is returned
/// when a match is found. Ok(None) is returned when there is definitively
/// no match. Err(()) is returned when this routine could not detect
/// whether there was a match or not.
fn fast_find(
    &self,
    haystack: &[u8],
    at: usize,
) -> Result<Option<Match>, ()> {
    // This is a bit hairy. The whole point here is to avoid running a
    // slower regex engine to extract capture groups. Remember, our word
    // regex looks like this:
    //
    //     (^|\W)(<original regex>)(\W|$)
    //
    // What we want are the match offsets of <original regex>. So in the
    // easy/common case, the original regex will be sandwiched between
    // two codepoints that are in the \W class. So our approach here is to
    // look for a match of the overall word regexp, strip the \W ends and
    // then check whether the original regex matches what's left. If so,
    // then we are guaranteed a correct match.
    //
    // This only works though if we know that the match is sandwiched
    // between two \W codepoints. The suffix side is easy: since \W is
    // preferred over `$` in the trailing alternation, `$` can only be
    // the branch that participated when the match ends at the end of the
    // haystack. (Anywhere else, if `$` could match before a line
    // terminator, then `\W` would have matched the line terminator
    // instead.) So we bail out when the match ends at the end of the
    // haystack and strip the last character otherwise.
    //
    // The prefix side is trickier, because `^` is preferred over `\W`
    // and `^` is a *line* anchor that matches at the start of any line,
    // not just at the start of the haystack. So when a match starts at
    // the beginning of a line, the `^` branch may have participated, in
    // which case the first character of the overall match is part of the
    // original match and must not be stripped. Since `^` is the preferred
    // branch, we know that if the original regex can match everything
    // in the overall match except for the trailing \W character, then it
    // must be the `^` branch that participated. So at a line start, we
    // first try the "no prefix stripped" interpretation and only fall
    // back to stripping the leading character if that fails.
    let config = self.chir.config();
    let configured_term = config.line_terminator;
    let search_term = self.chir.line_terminator();
    let non_matching = non_matching_bytes(self.chir.hir());
    let input = Input::new(haystack).span(at..haystack.len());
    match self.regex.find(input) {
        None => Ok(None),
        Some(m) => {
            let cand = Match::new(m.start(), m.end());
            let haystack_len = haystack.len();
            let at_start = cand.start() == 0;
            let at_end = cand.end() == haystack_len;
            if at_start || at_end {
                return Err(());
            }
            let slice = &haystack[cand];
            let cand_len = cand.len();
            let cand_empty = cand.is_empty();
            let (prefix_ch, slen) = if cand_empty || slice.is_empty() {
                (None, 0)
            } else if slice[0] <= 0x7F {
                (Some(slice[0] as char), 1)
            } else {
                bstr::decode_utf8(slice)
            };
            let (suffix_ch, elen) = if cand_empty || slice.is_empty() {
                (None, 0)
            } else if slice[cand_len - 1] <= 0x7F {
                (Some(slice[cand_len - 1] as char), 1)
