            let slen = match prefix_ch {
                Some(ch) => ch.len_utf8(),
                None => slen,
            };
            let elen = match suffix_ch {
                Some(ch) => ch.len_utf8(),
                None => elen,
            };
            let new_end = cand.end() - elen;
            if new_end > haystack_len {
                return Err(());
            }
