            // the leading alternation may be what participated, in which
            // case nothing should be stripped from the start of the
            // match. Since `^` is the preferred branch, if the original
            // regex matches the unstripped span, then `^` necessarily
            // participated and this is the correct inner match.
            if haystack[cand.start() - 1] == b'\n' {
                let inner_match = Match::new(cand.start(), new_end);
                if let Some(m) = self.confirm_inner(
                    haystack,
                    inner_match,
                    non_matching,
                    configured_term,
                    search_term,
                )? {
                    return Ok(Some(m));
                }
            }
            let new_start = cand.start() + slen;
