                None => Err(()),
            }
        }
    }
}

/// Run the standard battery of checks on the given candidate inner match
/// (i.e., the span we believe corresponds to the original regex). If all
/// checks pass and the original regex matches the candidate span, then
/// the corresponding match is returned. Otherwise, None is returned to
/// indicate that this candidate is not a valid inner match.
fn confirm_inner(
    &self,
    haystack: &[u8],
    inner_match: Match,
    non_matching: ByteSet,
    configured_term: Option<LineTerminator>,
    search_term: Option<LineTerminator>,
) -> Result<Option<Match>, ()> {
    let inner = &haystack[inner_match];
    let inner_len = inner_match.len();
    let mut inner_impossible = inner_len > 0;
    let mut i = 0;
    while i < inner_len {
        let b = inner[i];
        if !non_matching.contains(b) {
            inner_impossible = false;
            break;
        }
        i += 1;
    }
    let term = if let Some(t) = search_term {
        Some(t)
    } else {
        configured_term
    };
    let mut blocked = inner_impossible;
    if let Some(term) = term {
        if inner_len > 0 {
            if term.is_crlf() || self.chir.config().crlf {
                let mut j = 0;
                while j < inner_len {
                    let b = inner[j];
                    if b == b'\r' || b == b'\n' {
                        blocked = true;
                        break;
                    }
                    j += 1;
                }
            } else {
                let t = term.as_byte();
                let mut j = 0;
                while j < inner_len {
                    if inner[j] == t {
                        blocked = true;
                        break;
                    }
                    j += 1;
                }
            }
            if !blocked {
                if let Err(_) = strip_from_match(
                    Hir::literal(inner.to_vec()),
                    term,
                ) {
                    blocked = true;
                }
            }
        }
    }
    if blocked {
        Err(())
    } else if self.original.is_match(inner) {
        Ok(Some(inner_match))
    } else {
        Ok(None)
    }
}

