    // easy/common case, the original regex will be sandwiched between
    // two codepoints that are in the \W class. So our approach here is to
    // look for a match of the overall word regexp, strip the \W ends and
    // then check whether the original regex matches what's left. If so,
    // then we are guaranteed a correct match.
    //
    // This only works though if we know that the match is sandwiched
    // between two \W codepoints. This only occurs when neither ^ nor $
    // match. This in turn only occurs when the match is at either the
    // beginning or end of the haystack. In either of those cases, we
    // declare defeat and defer to the slower implementation.
    //
    // The reason why we cannot handle the ^/$ cases here is because we
    // can't assume anything about the original pattern. (Try commenting
    // out the checks for ^/$ below and run the tests to see examples.)
    let config = self.chir.config();
    let configured_term = config.line_terminator;
    let search_term = self.chir.line_terminator();
    let non_matching = non_matching_bytes(self.chir.hir());
    let input = Input::new(haystack).span(at..haystack.len());
    match self.regex.find(input) {
        None => Ok(None),
        Some(m) => {
            let cand = Match::new(m.start(), m.end());
            let haystack_len = haystack.len();
            let at_start = cand.start() == 0;
            let at_end = cand.end() == haystack_len;
            if at_start || at_end {
                return Err(());
            }
            let slice = &haystack[cand];
            let cand_len = cand.len();
            let cand_empty = cand.is_empty();
            let (prefix_ch, slen) = if cand_empty || slice.is_empty() {
                (None, 0)
            } else if slice[0] <= 0x7F {
                (Some(slice[0] as char), 1)
            } else {
                bstr::decode_utf8(slice)
            };
            let (suffix_ch, elen) = if cand_empty || slice.is_empty() {
                (None, 0)
            } else if slice[cand_len - 1] <= 0x7F {
                (Some(slice[cand_len - 1] as char), 1)
            } else {
                let mut start = cand_len - 1;
                let limit = cand_len.saturating_sub(4);
                while start > limit && slice[start] & 0xC0 == 0x80
                {
                    start -= 1;
                }
                let tail = &slice[start..];
                let (ch, size) = bstr::decode_utf8(tail);
                if start + size != cand_len {
                    (None, 1)
                } else {
                    (ch, size)
                }
            };
            let slen = match prefix_ch {
                Some(ch) => ch.len_utf8(),
                None => slen,
            };
            let elen = match suffix_ch {
                Some(ch) => ch.len_utf8(),
                None => elen,
            };
            let new_start = cand.start() + slen;
            let new_end = cand.end() - elen;
            if new_start > new_end {
                return Err(());
            }
            if new_start > haystack_len || new_end > haystack_len {
                return Err(());
            }
            let inner_match = Match::new(new_start, new_end);
            let inner = &haystack[inner_match];
            let inner_len = inner_match.len();
            let mut inner_impossible = inner_len > 0;
            let mut i = 0;
            while i < inner_len {
                let b = inner[i];
                if !non_matching.contains(b) {
                    inner_impossible = false;
                    break;
                }
                i += 1;
            }
            let term = if let Some(t) = search_term {
                Some(t)
            } else {
                configured_term
            };
            let mut blocked = inner_impossible;
            if let Some(term) = term {
                if inner_len > 0 {
                    if term.is_crlf() || config.crlf {
                        let mut j = 0;
                        while j < inner_len {
                            let b = inner[j];
                            if b == b'\r' || b == b'\n' {
                                blocked = true;
                                break;
                            }
                            j += 1;
                        }
                    } else {
                        let t = term.as_byte();
                        let mut j = 0;
                        while j < inner_len {
                            if inner[j] == t {
                                blocked = true;
                                break;
                            }
                            j += 1;
                        }
                    }
                    if !blocked {
                        if let Err(_) = strip_from_match(
                            Hir::literal(inner.to_vec()),
                            term,
                        ) {
                            blocked = true;
                        }
                    }
                }
            }
            if blocked {
                Err(())
            } else if self.original.is_match(inner) {
                Ok(Some(inner_match))
            } else {
                Err(())
            }
        }
    }
}

